files.content:
:root {
  --bg: #1a1c2c;
  --card: #2e3148;
  --text: #f4f4f4;
  --accent: #ff6b6b;
  --accent-hover: #ff8e8e;
  --border: #5a5f7d;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 8px;
  padding: 28px 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 8px 0 #12131f;
}

h1 {
  margin: 0 0 24px;
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.field {
  margin-bottom: 18px;
}

label {
  display: block;
  margin-bottom: 6px;
  font-size: 0.95rem;
  color: #b8bcd4;
}

input,
select {
  width: 100%;
  padding: 12px 14px;
  font-size: 1.1rem;
  font-family: inherit;
  color: var(--text);
  background: #23263a;
  border: 3px solid var(--border);
  border-radius: 6px;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input:focus,
select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.35);
}

button {
  width: 100%;
  margin-top: 6px;
  padding: 14px;
  font-size: 1.1rem;
  font-family: inherit;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #1a1c2c;
  background: var(--accent);
  border: none;
  border-radius: 6px;
  cursor: pointer;
  box-shadow: 0 5px 0 #b33a3a;
  transition: background 0.15s, transform 0.05s, box-shadow 0.05s;
}

button:hover {
  background: var(--accent-hover);
}

button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 3px;
}

button:active {
  transform: translateY(3px);
  box-shadow: 0 2px 0 #b33a3a;
}

.result-box {
  margin-top: 24px;
  padding: 16px;
  background: #23263a;
  border: 3px dashed var(--border);
  border-radius: 6px;
  text-align: center;
}

.result-label {
  display: block;
  font-size: 0.85rem;
  color: #b8bcd4;
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

#result {
  font-size: 1.8rem;
  font-weight: 700;
  word-break: break-all;
}

@media (max-width: 400px) {
  body {
    padding: 10px;
  }
  .card {
    padding: 20px 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
}

const leftInput = document.getElementById('left');
const rightInput = document.getElementById('right');
const operationSelect = document.getElementById('operation');
const calculateBtn = document.getElementById('calculate');
const resultOutput = document.getElementById('result');

function parseNumber(value) {
  if (value.trim() === '') return null;
  const num = Number(value);
  return Number.isFinite(num) ? num : null;
}

function calculate() {
  const left = parseNumber(leftInput.value);
  const right = parseNumber(rightInput.value);
  const operation = operationSelect.value;

  if (left === null || right === null) {
    resultOutput.textContent = 'Error';
    return;
  }

  let result;
  switch (operation) {
    case 'add':
      result = left + right;
      break;
    case 'subtract':
      result = left - right;
      break;
    case 'multiply':
      result = left * right;
      break;
    case 'divide':
      if (right === 0) {
        resultOutput.textContent = 'Error';
        return;
      }
      result = left / right;
      break;
    default:
      resultOutput.textContent = 'Error';
      return;
  }

  if (!Number.isFinite(result)) {
    resultOutput.textContent = 'Error';
    return;
  }

  resultOutput.textContent = String(result);
}

calculateBtn.addEventListener('click', calculate);

[leftInput, rightInput, operationSelect].forEach(function (el) {
  el.addEventListener('keydown', function (event) {
    if (event.key === 'Enter') {
      event.preventDefault();
      calculate();
    }
  });
});
